 var builder = WebApplication.CreateBuilder(args);

 // Train and save the model at startup
 var mlContext = new MLContext(seed: 42);
 var dataPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "customers.csv");
 var modelPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "ChurnModel.zip");

 var dataView = mlContext.Data.LoadFromTextFile<CustomerInput>(dataPath, hasHeader: true, separatorChar: ',');

 // Map "Yes"/"No" to boolean Label
 var labelKeys = new[] { "Yes", "No" };
 var labelValues = new[] { true, false };

 var fullPipeline = mlContext.Transforms.Conversion.MapValue(
         "Label", new Dictionary<string, bool> { ["Yes"] = true, ["No"] = false }, inputColumnName: nameof(CustomerInput.Churned))
     .Append(mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerInput.Region)))
     .Append(mlContext.Transforms.Concatenate("Features",
         nameof(CustomerInput.Age),
         nameof(CustomerInput.Income),
         "RegionEncoded",
         nameof(CustomerInput.PurchaseHistory)))
     .Append(mlContext.Transforms.NormalizeMinMax("Features"))
     .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
         labelColumnName: "Label",
         featureColumnName: "Features"));

 var split = mlContext.Data.TrainTestSplit(dataView, testFraction: 0.2);
 var model = fullPipeline.Fit(split.TrainSet);

 // Evaluate (guard against small datasets where test set may lack positive/negative examples)
